140			}
141			return JSON_VIEW;
142		}
143	
144		/**
145		 * 신규 API - 동기화(임시)
146		 * GET /client/sync
147		 * 인증: 인터셉터에서 처리 (Authorization: Bearer {ACCESS_TOKEN})
