151		@Operation(summary = "동기화 (신규)", description = "신규 API 규격 - 클라이언트 동기화 데이터를 조회합니다")
152		@Parameters({
153			@Parameter(name = "X-Manufacturer", description = "단말 제조사", example = "samsung", required = true, in = ParameterIn.HEADER),
154			@Parameter(name = "X-Model", description = "단말 모델명", example = "SM-G998N", required = true, in = ParameterIn.HEADER),
