private ResultMap saveLoginSession(HttpSession session, ParamMap param, ResultMap loginInfo, int logSeq) {
	ResultMap resultMap = new ResultMap();

	long accountSeq = loginInfo.getLong("accountSeq");

	param.put("accountSeq", accountSeq);
	if(dao.checkBeforeLogin(param)) {
		resultMap.put("tokenErr", "001");
	} else {
		resultMap.put("tokenErr", "000");
		String loginToken = UUID.randomUUID().toString().replace("-", "");
		param.put("loginToken", loginToken);
		dao.updateLoginToken(param);
		session.setAttribute("loginToken", loginToken);
	}

	dao.updateLoginTime(accountSeq);

	ResultMap accountInfo = dao.getAccountInfo(accountSeq);
	String authzCode = accountInfo.getString("authz");
	String name = accountInfo.getString("name");
	String id = accountInfo.getString("id");
	String lastLoginTime =  accountInfo.getString("lastLoginTime");

	session.setAttribute("loginAccountSeq", accountSeq);
	session.setAttribute("loginId", id);
	session.setAttribute("loginName", name);
	session.setAttribute("loginAuthz", authzCode);
	session.setAttribute("lastLoginTime", lastLoginTime);

