private void requestSms(long accountSeq, String encPhoneNumber, SmsGubun gubun) throws Exception {
	ResultMap lastSmsInfo = dao.getSMSInfo(accountSeq);
	if (lastSmsInfo != null) {// SMS 인증  실패해서 이전 데이터가 남아있는 경우
		ParamMap param = new ParamMap();
		param.put("accountSeq", accountSeq);

		Date lastSmsReqTime = Time.toDate(lastSmsInfo.get("reqDate"));
		if (Time.compareDateTime(lastSmsReqTime, Time.getCurrentDateTime(), 30)) {
			logger.info("Last SMS fail time in 30 min range. account : " + accountSeq);
			int loginFailCnt = dao.getloginFailCount(accountSeq);
			param.put("loginFailCnt", ++loginFailCnt);

			if (loginFailCnt >= 5) {
				dao.updateloginFailCount(param);
				throw new LogicException("SMS LOCK", "501"); 
			}
		} else {
			param.put("loginFailCnt", 0);
		}
		dao.updateloginFailCount(param);
	}

	String passcode = generateRandom(6);

	String message = prefix + " " + passcode + " " + postfix;
	String sendNum = securityModule.AES256_Encrypt(sendNumber).trim();
	int logSeq = 0;
	logger.info("[STEP {}] - Request SMS", ++ logSeq);
	logger.info("[STEP {}] - Account Seq: " + accountSeq, ++ logSeq);
	logger.info("[STEP {}] - From: " + sendNumber, ++ logSeq);
	logger.info("[STEP {}] - To: [MASKED]", ++ logSeq);
	logger.info("[STEP {}] - Passcode: " + passcode, ++ logSeq);
	logger.info("[STEP {}] - SMS Type: " + gubun.toString(), ++ logSeq);

	ParamMap batchParam = new ParamMap();
	long seq = dao.getNextSmsSeq();
	batchParam.put("smsSeq", seq);
	batchParam.put("message", message);
	batchParam.put("sendNum", sendNum);
	batchParam.put("targetNum", encPhoneNumber);
	dao.setSMSBatch(batchParam);

	ParamMap smsParam = new ParamMap();
	smsParam.put("accountSeq", accountSeq);
	smsParam.put("certificationNo", passcode);
	smsParam.put("reqDate", Time.getCurrentDateTime());
	smsParam.put("smsGubun", gubun.toString());
	dao.setSMSInfo(smsParam);
}

