public String hmacSha256(String plaintext) {
    if (plaintext == null || plaintext.isEmpty()) {
        return "";
    }
    try {
        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec keySpec = new SecretKeySpec(
                pepper.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
        mac.init(keySpec);
        byte[] hash = mac.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));
        return bytesToHex(hash);
    } catch (Exception e) {
        logger.error("HashUtil - [hmacSha256] ERROR", e);
        throw new RuntimeException("HMAC-SHA-256 hash generation failed", e);
    }
}

private static String bytesToHex(byte[] bytes) {
    StringBuilder sb = new StringBuilder(bytes.length * 2);
    for (byte b : bytes) {
        sb.append(String.format("%02x", b));
    }

