package com.ahope.ds.blackbox;

import static com.ahope.ds.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.loginAdmin;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.testId;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.nullValue;

import java.util.Map;

import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import com.ahope.ds.blackbox.support.BlackBoxSupport;

import io.restassured.filter.cookie.CookieFilter;

/**
 * Black-Box API Integration Test
 *
 * @target-controller MemberController (src/main/java/com/ahope/ds/web/admin/member/controller/MemberController.java)
 * @target-api GET /web/admin/members/qos/{memberSeq}
 *
 * 인증: AdminLoginInterceptor (세션). SYSTEM(07) 관리자로 2단계 로그인.
 * 예외는 CommonController 가 HTTP 200 + {err} JSON(X-Requested-With 필요)로 반환한다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class MemberQosStatusBlackBoxTest {

    private Map<String, String> seed(TestInfo info, String qos) {
        long acc = testSeq(info);
        long member = acc + 1;
        return Map.of(
                "ACC", Long.toString(acc),
                "ID", "bb" + testId(info),
                "MEMBER", Long.toString(member),
                "QOS", qos);
    }

    private CookieFilter arrange(Map<String, String> p) {
        executeSqlTemplate("sql/members-qos-teardown.sql", p);
        executeSqlTemplate("sql/members-qos-setup.sql", p);
        return loginAdmin(p.get("ID"), "Test1234!", Long.parseLong(p.get("ACC")));
    }

    @Test
    void NTC_qos_status01(TestInfo info) {
        Map<String, String> p = seed(info, "01");
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
            .when()
                    .get("/web/admin/members/qos/" + p.get("MEMBER"))
            .then()
                    .statusCode(200)
                    .body("err", equalTo("000"))
                    .body("memberQosStatus.qosStatus", equalTo("01"));
        } finally {
            executeSqlTemplate("sql/members-qos-teardown.sql", p);
        }
    }

    @Test
    void NTC_qos_status02(TestInfo info) {
        Map<String, String> p = seed(info, "02");
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
            .when()
                    .get("/web/admin/members/qos/" + p.get("MEMBER"))
            .then()
                    .statusCode(200)
                    .body("err", equalTo("000"))
                    .body("memberQosStatus.qosStatus", equalTo("02"));
        } finally {
            executeSqlTemplate("sql/members-qos-teardown.sql", p);
        }
    }

    @Test
    void NTC_qos_absentMember(TestInfo info) {
        Map<String, String> p = seed(info, "01");
        CookieFilter cookies = arrange(p);
        try {
            // 존재하지 않는 memberSeq → 조회 결과 null, 정상 응답 err=000
            long absent = Long.parseLong(p.get("MEMBER")) + 500;
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
            .when()
                    .get("/web/admin/members/qos/" + absent)
            .then()
                    .statusCode(200)
                    .body("err", equalTo("000"))
                    .body("memberQosStatus", nullValue());
        } finally {
            executeSqlTemplate("sql/members-qos-teardown.sql", p);
        }
    }

    @Test
    void VTC_memberSeq_nonNumeric(TestInfo info) {
        Map<String, String> p = seed(info, "01");
        CookieFilter cookies = arrange(p);
        try {
            // 경로변수 타입 불일치 → CommonController 예외핸들러 → 200 + err=999
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
            .when()
                    .get("/web/admin/members/qos/not-a-number")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("999"));
        } finally {
            executeSqlTemplate("sql/members-qos-teardown.sql", p);
        }
    }

    // referenced to keep import used across helper
    @SuppressWarnings("unused")
    private static final Class<?> SUPPORT = BlackBoxSupport.class;
}

