 *
 * NTC(정상 복호화) 한계: 개인정보 암호화는 서버측 KMS(dataEncryptionService)로만 수행되며
 * 순수 HTTP 경로에 개인정보 '암호화' 엔드포인트가 없어 유효 암호문을 블랙박스로 생성할 수 없다.
 * 따라서 값을 임의 생성(hallucination)하지 않고, 결정적으로 검증 가능한 필수값/무효암호문 계약만 검증한다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class CryptoPersonalBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long acc = testSeq(info);
        return Map.of(
                "ACC", Long.toString(acc),
                "ID", "bb" + testId(info));
    }

    private CookieFilter arrange(Map<String, String> p) {
        executeSqlTemplate("sql/crypto-personal-teardown.sql", p);
        executeSqlTemplate("sql/crypto-personal-setup.sql", p);
        return loginAdmin(p.get("ID"), "Test1234!", Long.parseLong(p.get("ACC")));
    }

    @Test
    void VTC_cryptoContent_NULL(TestInfo info) {
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            // cryptoContent 미전송 → RequestParamMap requiredValues → err=001
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .contentType(ContentType.URLENC)
            .when()
                    .post("/web/super/admin/crypto/personal")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("001"));
        } finally {
            executeSqlTemplate("sql/crypto-personal-teardown.sql", p);
        }
    }

    @Test
    void VTC_cryptoContent_EMPTY(TestInfo info) {
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            // 빈 문자열은 CommonUtil.isNull 상 null 로 취급 → err=001
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .contentType(ContentType.URLENC)
                    .formParam("cryptoContent", "")
            .when()
                    .post("/web/super/admin/crypto/personal")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("001"));
        } finally {
            executeSqlTemplate("sql/crypto-personal-teardown.sql", p);
        }
    }

    @Test
    void ATC_cryptoContent_invalidCipher(TestInfo info) {
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            // 복호화 불가한 값 → dataEncryptionService RuntimeException → err=115
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .contentType(ContentType.URLENC)
                    .formParam("cryptoContent", "not-a-valid-ciphertext")
            .when()
                    .post("/web/super/admin/crypto/personal")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("115"));
        } finally {
            executeSqlTemplate("sql/crypto-personal-teardown.sql", p);
        }
    }

    @Test
    void ATC_cryptoContent_specialChar(TestInfo info) {
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .contentType(ContentType.URLENC)
                    .formParam("cryptoContent", "'; DROP TABLE ACCOUNT--")
            .when()
                    .post("/web/super/admin/crypto/personal")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("115"));
        } finally {
            executeSqlTemplate("sql/crypto-personal-teardown.sql", p);
        }
    }
}

