import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.filter.cookie.CookieFilter;

/**
 * Black-Box API Integration Test
 *
 * @target-controller QuotaController (src/main/java/com/ahope/ds/web/admin/quota/controller/QuotaController.java)
 * @target-api DELETE /web/admin/quota/groups
 *
 * 인증: AdminLoginInterceptor. 고객사형 관리자 NORMAL(02), CLIENT_ADDITIONAL_INFO.QUOTA_ONOFF='01' 필수(아니면 403).
 * 요청: memberGroupSeqs[] (long[]). 응답: ResultMap {err:000, removeCnt}. 삭제 0건 → LogicException("008").
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class QuotaDeleteGroupBlackBoxTest {

    private long g1, g2, g3;

    private Map<String, String> seed(TestInfo info) {
        long acc = testSeq(info);
        long client = acc + 1;
        g1 = client * 10 + 1;
        g2 = client * 10 + 2;
        g3 = client * 10 + 3;
        return Map.of(
                "ACC", Long.toString(acc),
                "ID", "bb" + testId(info),
                "CLIENT", Long.toString(client),
                "G1", Long.toString(g1),
                "G2", Long.toString(g2),
                "G3", Long.toString(g3));
    }

    private CookieFilter arrange(Map<String, String> p) {
        executeSqlTemplate("sql/quota-groups-teardown.sql", p);
        executeSqlTemplate("sql/quota-groups-setup.sql", p);
        return loginAdmin(p.get("ID"), "Test1234!", Long.parseLong(p.get("ACC")));
    }

    private long groupCount(long client) {
        return Long.parseLong(queryScalar(
                "SELECT COUNT(*) FROM MEMBER_GROUP WHERE CLIENT_SEQ = ?", client));
    }

    @Test
    void NTC_delete_twoOfThree(TestInfo info) {
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        long client = Long.parseLong(p.get("CLIENT"));
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .queryParam("memberGroupSeqs[]", g1, g2)
            .when()
                    .delete("/web/admin/quota/groups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("000"))
                    .body("removeCnt", equalTo(2));

            // 3건 중 2건 삭제 → 1건 남음
            assertEquals(1L, groupCount(client));
        } finally {
            executeSqlTemplate("sql/quota-groups-teardown.sql", p);
        }
    }

    @Test
    void NTC_delete_single(TestInfo info) {
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        long client = Long.parseLong(p.get("CLIENT"));
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .queryParam("memberGroupSeqs[]", g1)
            .when()
                    .delete("/web/admin/quota/groups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("000"))
                    .body("removeCnt", equalTo(1));

            assertEquals(2L, groupCount(client));
        } finally {
            executeSqlTemplate("sql/quota-groups-teardown.sql", p);
        }
    }

    @Test
    void NTC_delete_all(TestInfo info) {
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        long client = Long.parseLong(p.get("CLIENT"));
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .queryParam("memberGroupSeqs[]", g1, g2, g3)
            .when()
                    .delete("/web/admin/quota/groups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("000"))
                    .body("removeCnt", equalTo(3));

            assertEquals(0L, groupCount(client));
        } finally {
            executeSqlTemplate("sql/quota-groups-teardown.sql", p);
        }
    }

    @Test
    void ATC_delete_nonexistentGroups(TestInfo info) {
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            // 존재하지 않는 seq → affected=0 → LogicException GROUP_NOT_FOUND("008")
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .queryParam("memberGroupSeqs[]", g1 + 900000, g2 + 900000)
            .when()
                    .delete("/web/admin/quota/groups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("008"));
        } finally {
            executeSqlTemplate("sql/quota-groups-teardown.sql", p);
        }
    }
}

