package com.ahope.ds.blackbox;

import static com.ahope.ds.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.hmacSha256;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.testId;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.not;
import static org.hamcrest.Matchers.emptyOrNullString;

import java.util.HashMap;
import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;
import io.restassured.specification.RequestSpecification;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ClientAPIController (src/main/java/com/ahope/ds/client/controller/ClientAPIController.java)
 * @target-api GET /client/sync
 *
 * 인증: ClientLoginInterceptor. Authorization: Bearer {ACCESS_TOKEN} (KMS 암호화 JSON).
 * 토큰은 POST /client/init 로만 발급되므로 NTC 는 실제 init 왕복으로 토큰을 확보한다.
 * 응답: ClientResultMap {code:"200", message, data:{...}}. 예외 시 code=에러코드.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ClientSyncBlackBoxTest {

    private static final String BG_URL = "http://img.example/bb-bg.png";
    private static final String APP_VER = "7";
    private static final String NOTICE_VER = "5";

    private String ctn;

    private Map<String, String> seed(TestInfo info) {
        long client = testSeq(info);
        long member = client + 1;
        ctn = "010" + testId(info).substring(1); // "T000..." → "010000..."
        Map<String, String> p = new HashMap<>();
        p.put("CLIENT", Long.toString(client));
        p.put("MEMBER", Long.toString(member));
        p.put("CTN", ctn);
        p.put("CTN_HASH", hmacSha256(ctn));
        p.put("BG_URL", BG_URL);
        p.put("APP_VER", APP_VER);
        p.put("TERMS_SEQ", Long.toString(client + 2));
        p.put("NOTICE_SEQ", Long.toString(client + 3));
        p.put("NOTICE_VER", NOTICE_VER);
        return p;
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/client-sync-teardown.sql", p);
        executeSqlTemplate("sql/client-sync-setup.sql", p);
    }

    /** 단말 필수 헤더가 포함된 요청 스펙. */
    private RequestSpecification device() {
        return given().baseUri(BASE_URL)
                .header("X-Manufacturer", "samsung")
                .header("X-Model", "SM-G998N")
                .header("X-OS-Version", "14")
                .header("X-App-Version", "02.00.01");
    }

    /** 실제 /client/init 호출로 유효한 KMS Bearer 토큰을 발급받는다. */
    private String issueAccessToken(TestInfo info) {
        return device()
                .contentType(ContentType.JSON)
                .body("{\"ctn\":\"" + ctn + "\",\"fcmToken\":\"fcm-" + testId(info) + "\"}")
        .when()
                .post("/client/init")
        .then()
                .statusCode(200)
                .body("code", equalTo("200"))
                .body("data.accessToken", not(emptyOrNullString()))
                .extract().path("data.accessToken");
    }

    @Test
    void NTC_sync_backgroundImage(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            String token = issueAccessToken(info);
            device().header("Authorization", "Bearer " + token)
            .when()
                    .get("/client/sync")
            .then()
                    .statusCode(200)
                    .body("code", equalTo("200"))
                    .body("data.mainBackgroundImageUrl", equalTo(BG_URL));
        } finally {
            executeSqlTemplate("sql/client-sync-teardown.sql", p);
        }
    }

    @Test
    void NTC_sync_interlockingAppVersion(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            String token = issueAccessToken(info);
            device().header("Authorization", "Bearer " + token)
            .when()
                    .get("/client/sync")
            .then()
                    .statusCode(200)
                    .body("code", equalTo("200"))
                    .body("data.interlockingAppVersion", equalTo(Integer.parseInt(APP_VER)));
        } finally {
            executeSqlTemplate("sql/client-sync-teardown.sql", p);
        }
    }

    @Test
    void NTC_sync_solutionListEmpty(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            String token = issueAccessToken(info);
            device().header("Authorization", "Bearer " + token)
            .when()
                    .get("/client/sync")
            .then()
                    .statusCode(200)
                    .body("code", equalTo("200"))
                    .body("data.solutionList.size()", equalTo(0));
        } finally {
            executeSqlTemplate("sql/client-sync-teardown.sql", p);
        }
    }

    @Test
    void VTC_authorization_missing(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            // Authorization 헤더 없음 → 인터셉터 MISSING_TOKEN → code=816
            device()
            .when()
                    .get("/client/sync")
            .then()
                    .statusCode(200)
